const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southPoint = ee.Geometry.Point(110.2273416, -8.879787); // Southern coastal waters of Java
  const northPoint = ee.Geometry.Point(109.953683, -5.741852);  // Northern Java Sea waters

  const targetDate = ee.Date('2019-08-04');
  // MODIS-Aqua L3 CHLA 8-day product's `system:time_start` is the beginning of the 8-day period.
  // We want the 8-day composite that *contains* August 4, 2019.
  // The product has `system:time_start` values like '2019-07-31', '2019-08-08', etc.
  // So, for '2019-08-04', we need the composite starting '2019-07-31'.
  const startDate = targetDate.advance(-4, 'day'); // Roughly center the search window for 8-day products
  const endDate = targetDate.advance(4, 'day');

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3/CHLA/8D')
    .filterDate(startDate, endDate)
    .select('chlor_a');

  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No images found for the specified date range.");
    console.log("C1");
    return;
  }

  // Get the image whose 8-day period covers the target date.
  // For '2019-08-04', the relevant 8-day composite usually starts on '2019-07-31'.
  // We'll pick the image whose `system:time_start` is closest to or just before the targetDate.
  const image = await collection
    .filter(ee.Filter.lte('system:time_start', targetDate.millis()))
    .sort('system:time_start', false) // Get the latest image that starts before or on the target date
    .first();

  if (!image) {
    console.log("Could not find a suitable MODIS image for the target date.");
    console.log("C1");
    return;
  }

  const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();
  console.log(`Using image from starting date: ${imageDate}`);

  // Define a scale for reduceRegion. MODIS-Aqua L3 CHLA has a nominal resolution of ~4km.
  const scale = 4000;

  // 3. Processing & 4. Calculation
  // Calculate chlorophyll-a for the southern point
  const southChla = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southPoint,
    scale: scale,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  // Calculate chlorophyll-a for the northern point
  const northChla = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northPoint,
    scale: scale,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  // 5. Validation & Final Answer
  console.log(`Chlorophyll-a Southern Point: ${southChla}`);
  console.log(`Chlorophyll-a Northern Point: ${northChla}`);

  if (southChla === null || isNaN(southChla) || northChla === null || isNaN(northChla)) {
    console.log("C3"); // Calculation failed, likely no valid pixels at one or both points
  } else if (southChla > northChla) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
